# Human lung cancer: PC-9 empty vector (group A, osimertinib-sensitive) vs PC-9 TP53 R248Q
# (group B, gain-of-function mutant with early osimertinib resistance), DMSO vs osimertinib 24 h.
# Data: GEO GSE232890, raw counts generated by NCBI. 2 replicates per group.
# Run from this folder:  Rscript run_r.R

library(orthoresponse)

dir.create("data", showWarnings = FALSE)
fetch <- function(url, dest) {
  if (!file.exists(dest)) download.file(url, dest, mode = "wb")
  magic <- readBin(dest, "raw", 2)
  if (!identical(magic, as.raw(c(0x1f, 0x8b)))) {
    file.remove(dest)
    stop(url, " did not return a gzip file (NCBI sometimes asks for a browser check). ",
         "Download it with a web browser and save it as ", dest)
  }
  dest
}
counts_url <- paste0("https://www.ncbi.nlm.nih.gov/geo/download/?type=rnaseq_counts&acc=GSE232890",
                     "&format=file&file=GSE232890_raw_counts_GRCh38.p13_NCBI.tsv.gz")
info_url <- "https://ftp.ncbi.nlm.nih.gov/gene/DATA/GENE_INFO/Mammalia/Homo_sapiens.gene_info.gz"

counts <- read.delim(fetch(counts_url, "data/GSE232890_raw_counts_GRCh38.p13_NCBI.tsv.gz"), row.names = 1,
                     check.names = FALSE)
info <- read.delim(fetch(info_url, "data/Homo_sapiens.gene_info.gz"), quote = "")[, c("GeneID", "Symbol")]
samples <- read.delim("samples.tsv", row.names = 1)

res <- orthoresponse(counts, samples,
                     group_col = "line", condition_col = "treatment",
                     group_a = "EV", group_b = "R248Q",   # A = sensitive, B = resistant
                     control = "DMSO", stress = "Osimertinib")
res$classification$symbol <- info$Symbol[match(res$classification$feature, info$GeneID)]
res
save_orthoresponse(res, "results_r")

sr3 <- subset(res$classification, label == "stress_ready_3")
sr3 <- sr3[order(-sr3$a_response_log2FoldChange), c("symbol", "a_response_log2FoldChange", "basal_log2FoldChange")]
print(head(sr3, 20))

png(file.path("results_r", "model_patterns.png"), width = 1600, height = 1500, res = 170)
plot_model_patterns(res$classification, condition_labels = c("DMSO", "Osi"))
dev.off()
